-- CAB-0016: scoped editorial import. Deploy portrait/logo assets before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='government' and type='bloc') then raise exception 'CAB-0016: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pkr' and type='party') then raise exception 'CAB-0016: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('zulkifli-hasan','mohammed-taufiq-johari') and (type <> 'politician' or owner_id is not null)) then raise exception 'CAB-0016: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('sungai petani') and slug not in ('zulkifli-hasan','mohammed-taufiq-johari')) then raise exception 'CAB-0016: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'CAB-0016:%' and (m.source_type <> 'editorial' or e.slug not in ('zulkifli-hasan','mohammed-taufiq-johari') or m.import_key not like 'CAB-0016:' || e.slug || ':%')) then raise exception 'CAB-0016: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'zulkifli-hasan','Zulkifli Hasan','government','Minister in the Prime Minister’s Department (Religious Affairs)',null,null,'Zulkifli Hasan is Minister in the Prime Minister’s Department (Religious Affairs). He serves as a senator appointed by the Yang di-Pertuan Agong.','https://www.islam.gov.my/','/portraits/zulkifli-hasan.webp','https://www.parlimen.gov.my/images/webuser/ahli/2023/TMA.png','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Dewan Negara", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dn&id=4290"}]'::jsonb from public.entities parent where parent.slug='government' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'mohammed-taufiq-johari','Mohammed Taufiq Johari','government','Minister of Youth and Sports','Sungai Petani','Kedah','Mohammed Taufiq Johari is Minister of Youth and Sports. He represents Sungai Petani, Kedah, in the Dewan Rakyat. He is a member of Parti Keadilan Rakyat (PKR).','https://www.kbs.gov.my/','/portraits/mohammed-taufiq-johari.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P015.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Sungai Petani", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4054"}, {"label": "PKR · representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}]'::jsonb from public.entities parent where parent.slug='pkr' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('zulkifli-hasan','mohammed-taufiq-johari') and type='politician' and owner_id is null) <> 2 then raise exception 'CAB-0016: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0016:zulkifli-hasan:pondok-education-framework','Develop a strengthened national pondok-education framework','Education','in_progress',null,null,'2026-06-08','https://www.bernama.com/en/general/news.php?id=2566228','2026-06-08','https://www.bernama.com/en/general/news.php?id=2566228','Zulkifli said religious agencies and pondok institutions were developing a more dynamic educational framework while preserving their study traditions.','The minister described ongoing engagement and framework development involving JAKIM, YADIM and pondok institutions. Maintenance funding and previous-year repairs do not establish completion of this framework. A final framework, deadline and numerical completion were not verified.','2026-11-09','editorial',false from public.entities e where e.slug='zulkifli-hasan' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0016:zulkifli-hasan:kafa-pretahfiz-federal-territories','Expand KAFA Pre-Tahfiz to the Federal Territories','Education',null,null,null,'2026-10-28','https://www.bernama.com/en/news.php?id=2626832',null,null,'Zulkifli announced expansion of the KAFA Pre-Tahfiz programme from its Melaka pilot to suitable schools in the Federal Territories.','The announcement describes the intended expansion. Pilot pupil results and nationwide enrolment are not proof of delivery in the Federal Territories. No completed rollout, firm deadline or completion percentage was established.','2026-11-09','editorial',false from public.entities e where e.slug='zulkifli-hasan' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0016:mohammed-taufiq-johari:asian-games-six-gold','Meet the six-gold target at the 2026 Asian Games','Other','achieved',null,'2026-10-04','2026-09-14','https://web26.bernama.com/en/news.php?id=2607338','2026-09-28','https://web26.bernama.com/en/news.php?id=2612757','Mohammed Taufiq publicly supported the national contingent’s six-gold target for the Aichi-Nagoya 2026 Asian Games.','His 28 September update confirms six gold medals had been won. Achieved is limited to this gold-medal threshold. Credit belongs collectively to athletes, coaches, associations and supporting agencies; this is not an overall ministerial or Games performance score.','2026-11-09','editorial',false from public.entities e where e.slug='mohammed-taufiq-johari' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0016:mohammed-taufiq-johari:asian-para-games-medal-target','Pursue the 2026 Asian Para Games target of 6 gold, 10 silver and 16 bronze','Other',null,null,null,'2026-10-08','https://web26.bernama.com/en/sports/news.php?id=2617105','2026-10-24','https://web26.bernama.com/en/news.php?id=2625079','Mohammed Taufiq backed the national para contingent’s target of six gold, ten silver and sixteen bronze medals.','The 24 October report gives a 10 am snapshot of six gold, eight silver and thirteen bronze medals. The gold threshold was met, but the other two targets were below their thresholds in that snapshot. A comparable final Games total was not verified, so overall status and completion remain unknown.','2026-11-09','editorial',false from public.entities e where e.slug='mohammed-taufiq-johari' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milest